const mqtt = require("mqtt");

function createMqttBridge({ config, io, runtime }) {
  let client = null;
  let publishQueue = [];
  let publishTimer = null;

  const publishOptions = {
    [config.topics.plcChanges]: { qos: 0, retain: false },
    [config.topics.plcData]: { qos: 1, retain: true },
    [config.topics.plcStatus]: { qos: 1, retain: true },
    [config.topics.readRequest]: { qos: 1, retain: false },
    [config.topics.writeRequest]: { qos: 1, retain: false },
    [config.topics.writeConfirm]: { qos: 1, retain: false },
  };

  const subscribeOptions = {
    qos: 1,
  };

  function publishNow(topic, payload) {
    if (!client || !runtime.state.mqtt.connected) return;
    client.publish(topic, JSON.stringify(payload), publishOptions[topic] || { qos: 0, retain: false });
  }

  function flushPublishQueue() {
    if (publishQueue.length === 0) {
      clearInterval(publishTimer);
      publishTimer = null;
      return;
    }

    const next = publishQueue.shift();
    publishNow(next.topic, next.payload);
  }

  function publish(topic, payload) {
    const maxRate = Math.max(1, config.mqtt.maxMessagesPerSecond || 10);
    const intervalMs = Math.ceil(1000 / maxRate);

    publishQueue.push({ topic, payload });

    if (publishQueue.length === 1) {
      flushPublishQueue();
      return;
    }    
    if (!publishTimer) {
      flushPublishQueue();
      publishTimer = setInterval(flushPublishQueue, intervalMs);
    }
  }

  const publisher = {
    publishSnapshot: (data) => publish(config.topics.plcData, data),
    publishChanges: (payload) => publish(config.topics.plcChanges, payload),
    publishStatus: (payload) => publish(config.topics.plcStatus, payload),
    publishWriteConfirm: (result) => publish(config.topics.writeConfirm, result),
  };

  function start() {
    if (!config.mqtt.enabled) {
      runtime.updateMqttState({ enabled: false, connected: false, source: "mqtt-disabled" });
      return null;
    }

    client = mqtt.connect(config.mqtt.url, {
      connectTimeout: 5000,
      clientId: config.mqtt.clientId,
      keepalive: 60,
      clean: true,
      reconnectPeriod: config.mqtt.reconnectMs,
    });

    client.on("connect", () => {
      console.log("Cliente MQTT conectado.");
      client.subscribe([
        config.topics.readRequest,
        config.topics.writeRequest,
        config.topics.plcData,
        config.topics.plcChanges,
        config.topics.plcStatus,
        config.topics.writeConfirm,
      ], subscribeOptions);
      runtime.updateMqttState({
        enabled: true,
        connected: true,
        error: null,
        url: config.mqtt.url,
        source: "mqtt-connect",
      });
      runtime.publishPlcData().catch((error) => {
        console.error("No se pudo publicar snapshot post-reconexion MQTT:", error.message);
      });
    });

    client.on("reconnect", () => {
      runtime.updateMqttState({ connected: false, source: "mqtt-reconnect" });
    });

    client.on("close", () => {
      runtime.updateMqttState({ connected: false, source: "mqtt-close" });
    });

    client.on("error", (error) => {
      runtime.updateMqttState({
        connected: false,
        error: error.message,
        source: "mqtt-error",
      });
    });

    client.on("message", handleMessage);

    return client;
  }

  async function handleMessage(topic, message) {
    try {
      if (topic === config.topics.readRequest) {
        await runtime.publishPlcData();
        return;
      }

      if (topic === config.topics.writeRequest) {
        await runtime.writePlc(JSON.parse(message.toString()));
        return;
      }

      if (topic === config.topics.plcData) {
        const payload = JSON.parse(message.toString());
        const data = Array.isArray(payload) ? payload : payload.data;
        runtime.applyIncomingData(data, "mqtt-plc-data");
        return;
      }

      if (topic === config.topics.plcChanges) {
        const payload = JSON.parse(message.toString());
        if (runtime.shouldApplyMessage(payload)) {
          io.emit("plc:changes", payload);
        }
        return;
      }

      if (topic === config.topics.plcStatus) {
        io.emit("plc:status", JSON.parse(message.toString()));
        return;
      }

      if (topic === config.topics.writeConfirm) {
        io.emit("write:update", JSON.parse(message.toString()));
      }
    } catch (error) {
      console.error(`Error procesando MQTT '${topic}':`, error.message);
    }
  }

  function stop() {
    if (publishTimer) clearInterval(publishTimer);
    if (client) client.end(true);
  }

  return {
    start,
    stop,
    publisher,
  };
}

module.exports = createMqttBridge;
